import { CsvParseError, parseCsv } from './csv.js';

/** Columns the CSV must contain (any order, extra columns are ignored with a warning). */
export const REQUIRED_COLUMNS = ['order_id', 'line_item_id', 'customer', 'product', 'amount', 'created_at', 'category'];

/** IDs starting with this prefix are generated by the database migration and are reserved. */
export const RESERVED_ID_PREFIX = 'LEGACY-';

export const LIMITS = {
  id: 100,
  customer: 200,
  product: 200,
  category: 100,
  maxAmount: 1_000_000_000,
  minYear: 2000,
  maxYear: 2100,
};

const CONTROL_CHARACTERS = /[\u0000-\u001f\u007f]/;

const normalizeHeader = (name) => name.replace(/^\uFEFF/, '').trim().toLowerCase().replace(/[\s-]+/g, '_');

function textField(value, column, limit, problems, { reservedPrefix = false } = {}) {
  const text = value.trim();
  if (text === '') {
    problems.push({ column, message: `${column} is required but the cell is empty.` });
    return null;
  }
  if (CONTROL_CHARACTERS.test(text)) {
    problems.push({ column, message: `${column} contains a line break or control character; put the value on a single line.` });
    return null;
  }
  if (text.length > limit) {
    problems.push({ column, message: `${column} is ${text.length} characters long; the maximum is ${limit}.` });
    return null;
  }
  if (reservedPrefix && text.toUpperCase().startsWith(RESERVED_ID_PREFIX)) {
    problems.push({ column, message: `${column} "${text}" starts with "${RESERVED_ID_PREFIX}", a prefix reserved for IDs the database assigns to old records. Use a different ID.` });
    return null;
  }
  return text;
}

/** Strict money parsing: plain digits with at most two decimals. Never rounds silently. */
export function parseAmount(raw) {
  const text = raw.trim();
  if (text === '') return { error: 'amount is required but the cell is empty.' };
  if (/^[-−]\s*(\d|\.\d)/.test(text)) return { error: `amount "${text}" is negative; amounts must be 0 or greater.` };
  if (/^[$€£¥₹]/.test(text) || /[$€£¥₹]$/.test(text) || /^[A-Za-z]{3}\s*\d/.test(text)) {
    return { error: `amount "${text}" contains a currency symbol or code; use plain digits such as 49.99.` };
  }
  if (/^\d{1,3}(,\d{3})+(\.\d+)?$/.test(text)) {
    return { error: `amount "${text}" contains a thousands separator; remove the comma (write ${text.replace(/,/g, '')}).` };
  }
  if (/^\d+,\d{1,2}$/.test(text)) {
    return { error: `amount "${text}" uses a comma as the decimal separator; use a dot instead (write ${text.replace(',', '.')}).` };
  }
  if (!/^(\d+(\.\d*)?|\.\d+)$/.test(text)) {
    return { error: `amount "${text}" is not a valid number; use plain digits such as 49.99 (no letters, spaces, percent signs or scientific notation).` };
  }
  const decimals = text.includes('.') ? text.split('.')[1].length : 0;
  if (decimals > 2) {
    return { error: `amount "${text}" has more than 2 decimal places; round it to cents in your spreadsheet (for example ${Number(text).toFixed(2)}).` };
  }
  const value = Number(text);
  if (!Number.isFinite(value)) return { error: `amount "${text}" is not a valid number.` };
  if (value > LIMITS.maxAmount) {
    return { error: `amount "${text}" is larger than the allowed maximum of ${LIMITS.maxAmount.toLocaleString('en-US')}; check for a typo.` };
  }
  return { value };
}

const DATE_PATTERN = /^(\d{4})-(\d{2})-(\d{2})(?:[Tt ](\d{2}):(\d{2})(?::(\d{2})(?:\.(\d{1,9}))?)?\s*(Z|z|[+-]\d{2}:?\d{2})?)?$/;

/**
 * ISO 8601 date (2026-09-28) or timestamp (2026-09-28T14:30:00Z, with optional offset).
 * A timestamp without a time zone is treated as UTC. Returns a normalised UTC ISO string.
 */
export function parseCreatedAt(raw) {
  const text = raw.trim();
  if (text === '') return { error: 'created_at is required but the cell is empty.' };
  const match = DATE_PATTERN.exec(text);
  if (!match) {
    return { error: `created_at "${text}" is not a valid ISO date; use YYYY-MM-DD (for example 2026-09-28) or YYYY-MM-DDTHH:MM:SSZ. In Excel, format the column with the custom format yyyy-mm-dd.` };
  }
  const [, y, mo, d, h = '0', mi = '0', se = '0', fraction = '', zone = 'Z'] = match;
  const [year, month, day, hour, minute, second] = [y, mo, d, h, mi, se].map(Number);

  const calendar = new Date(Date.UTC(year, month - 1, day));
  if (month < 1 || month > 12 || calendar.getUTCFullYear() !== year || calendar.getUTCMonth() !== month - 1 || calendar.getUTCDate() !== day) {
    return { error: `created_at "${text}" is not a real calendar date (check the month and day).` };
  }
  if (hour > 23 || minute > 59 || second > 59) {
    return { error: `created_at "${text}" has an invalid time (hours 00-23, minutes and seconds 00-59).` };
  }
  let offsetMinutes = 0;
  if (zone.toUpperCase() !== 'Z') {
    const digits = zone.replace(':', '');
    const offsetHours = Number(digits.slice(1, 3));
    const offsetMins = Number(digits.slice(3, 5));
    if (offsetHours > 23 || offsetMins > 59) return { error: `created_at "${text}" has an invalid time zone offset.` };
    offsetMinutes = (digits[0] === '-' ? -1 : 1) * (offsetHours * 60 + offsetMins);
  }
  if (year < LIMITS.minYear || year > LIMITS.maxYear) {
    return { error: `created_at "${text}" has the year ${year}, outside the supported range ${LIMITS.minYear}-${LIMITS.maxYear}; check for a typo.` };
  }
  const millis = Number((fraction + '000').slice(0, 3));
  const utc = Date.UTC(year, month - 1, day, hour, minute, second, millis) - offsetMinutes * 60_000;
  return { value: new Date(utc).toISOString() };
}

/**
 * Validate the text of an orders CSV file.
 *
 * Returns { rows, errors, warnings, stats }:
 *  - rows: valid, normalised rows ({ row, orderId, lineItemId, customer, product, amount, createdAt, category })
 *  - errors: [{ row, column, message }] (row is null for file-level problems such as a missing header)
 *  - warnings: [{ row, message }] that never block an import
 */
export function validateOrderCsv(text, { maxRows = 50_000, now = new Date() } = {}) {
  const errors = [];
  const warnings = [];
  const rows = [];
  const stats = { recordsRead: 0, blankRowsSkipped: 0, validRows: 0, rejectedRows: 0 };
  const fileError = (message) => errors.push({ row: null, column: null, message });
  const finish = () => {
    stats.validRows = rows.length;
    stats.rejectedRows = new Set(errors.filter((e) => e.row !== null).map((e) => e.row)).size;
    return { rows, errors, warnings, stats };
  };

  let records;
  try {
    ({ records } = parseCsv(text));
  } catch (error) {
    if (error instanceof CsvParseError) {
      errors.push({ row: error.row, column: null, message: error.message });
      return finish();
    }
    throw error;
  }

  const headerRecord = records[0];
  if (!headerRecord || headerRecord.blank) {
    fileError('The file is empty or its first row (the header) is blank. The first row must contain the column names.');
    return finish();
  }

  // ---- header ----
  const rawHeaders = headerRecord.fields;
  if (rawHeaders.length === 1 && /[;\t|]/.test(rawHeaders[0])) {
    fileError('The header row is not comma-separated (it looks like semicolons, tabs or pipes). In Excel use File > Save As > "CSV UTF-8 (Comma delimited) (*.csv)".');
    return finish();
  }
  const headers = rawHeaders.map(normalizeHeader);
  const seen = new Set();
  for (const name of headers) {
    if (name !== '' && seen.has(name)) fileError(`The column "${name}" appears more than once in the header row.`);
    seen.add(name);
  }
  const missing = REQUIRED_COLUMNS.filter((column) => !headers.includes(column));
  if (missing.length > 0) {
    fileError(`Missing required column(s): ${missing.join(', ')}. The header row must be exactly: ${REQUIRED_COLUMNS.join(',')} (found: ${rawHeaders.map((h) => h.trim()).join(', ') || 'nothing'}).`);
  }
  const extra = rawHeaders.filter((raw, index) => headers[index] !== '' && !REQUIRED_COLUMNS.includes(headers[index])).map((h) => h.trim());
  if (extra.length > 0) warnings.push({ row: 1, message: `Ignoring column(s) that are not part of the import format: ${extra.join(', ')}.` });
  if (errors.length > 0) return finish();

  const index = Object.fromEntries(REQUIRED_COLUMNS.map((column) => [column, headers.indexOf(column)]));
  const dataRecords = records.slice(1);
  const nonBlank = dataRecords.filter((record) => !record.blank);
  stats.recordsRead = nonBlank.length;
  stats.blankRowsSkipped = dataRecords.length - nonBlank.length;

  if (nonBlank.length === 0) {
    fileError('The file has a header but no data rows.');
    return finish();
  }
  if (nonBlank.length > maxRows) {
    fileError(`The file has ${nonBlank.length.toLocaleString('en-US')} data rows, which is more than the allowed maximum of ${maxRows.toLocaleString('en-US')}. Split the file into smaller files, or raise IMPORT_MAX_ROWS.`);
    return finish();
  }

  // ---- rows ----
  const firstRowOfLineItem = new Map();
  const orderShape = new Map(); // order_id -> { customer, day, row }
  const futureCutoff = now.getTime() + 24 * 60 * 60 * 1000;

  for (const record of nonBlank) {
    const { row, fields } = record;
    const problems = [];

    if (fields.length !== headers.length) {
      errors.push({
        row,
        column: null,
        message: `Expected ${headers.length} columns but found ${fields.length}. Check for a missing or extra comma; a value that contains a comma must be wrapped in double quotes.`,
      });
      continue;
    }
    const cell = (column) => fields[index[column]];

    const orderId = textField(cell('order_id'), 'order_id', LIMITS.id, problems, { reservedPrefix: true });
    const lineItemId = textField(cell('line_item_id'), 'line_item_id', LIMITS.id, problems, { reservedPrefix: true });
    const customer = textField(cell('customer'), 'customer', LIMITS.customer, problems);
    const product = textField(cell('product'), 'product', LIMITS.product, problems);
    const category = textField(cell('category'), 'category', LIMITS.category, problems);

    const amount = parseAmount(cell('amount'));
    if (amount.error) problems.push({ column: 'amount', message: amount.error });
    const createdAt = parseCreatedAt(cell('created_at'));
    if (createdAt.error) problems.push({ column: 'created_at', message: createdAt.error });

    if (lineItemId !== null) {
      // IDs are compared exactly (case-sensitive), matching the database's unique index.
      if (firstRowOfLineItem.has(lineItemId)) {
        problems.push({ column: 'line_item_id', message: `Duplicate line_item_id "${lineItemId}": it was already used in row ${firstRowOfLineItem.get(lineItemId)}. Every line item needs its own unique ID.` });
      } else {
        firstRowOfLineItem.set(lineItemId, row);
      }
    }

    if (problems.length > 0) {
      for (const problem of problems) errors.push({ row, ...problem });
      continue;
    }

    if (Date.parse(createdAt.value) > futureCutoff) {
      warnings.push({ row, message: `created_at ${createdAt.value.slice(0, 10)} is in the future; double-check the date.` });
    }
    const day = createdAt.value.slice(0, 10);
    const previous = orderShape.get(orderId);
    if (!previous) {
      orderShape.set(orderId, { customer, day, row });
    } else if (previous.customer !== customer || previous.day !== day) {
      warnings.push({
        row,
        message: `order_id "${orderId}" has a different ${previous.customer !== customer ? 'customer' : 'date'} than row ${previous.row}. All lines of one order normally share the same customer and date; daily order counts would otherwise count the order on each date.`,
      });
    }

    rows.push({ row, orderId, lineItemId, customer, product, amount: amount.value, createdAt: createdAt.value, category });
  }

  return finish();
}
